create or replace function public.record_public_marketing_event(p_event jsonb)returns void language plpgsql security definer set search_path=public as $$begin if p_event->>'type'not in('page_view','cta_click','demo_request','trial_signup','contact_sales','newsletter','demo_launch','roi_calculation','industry_view','comparison_view','marketing_conversion')or length(p_event->>'path')>300 or(p_event->>'sessionId')!~'^[0-9a-f-]{36}$'then raise exception'invalid event';end if;insert into marketing_events(event_type,path,session_hash,metadata)values(p_event->>'type',p_event->>'path',encode(digest(p_event->>'sessionId','sha256'),'hex'),coalesce(p_event->'metadata','{}'));end$$;
revoke all on function public.record_public_marketing_event(jsonb)from public;grant execute on function public.record_public_marketing_event(jsonb)to anon,authenticated;
